// The occupation catalog: career families, and the career tracks that add to
// the ones in data/careers.js. Every track compiles into the same shape the
// career engine already uses (see the header of data/careers.js), so hiring,
// reviews, promotion and NPC working lives treat old and new alike.
//
// An OCCUPATION is a profession (a title on a track). A TRACK is a ladder of
// titles that belong together. An EMPLOYER (engine/employers.js) is an
// organization. A JOB is a posting at an employer for a level of a track.
//
// Extra fields a track may carry (all optional, defaults in parentheses):
//   family     the career family it is shown under (from its category)
//   hours      contracted hours a week at full time (40)
//   schedule   'standard' | 'shifts' | 'nights' | 'rotating' | 'weekends' | 'seasonal' | 'flexible' | 'irregular' | 'on_call'
//   remote     'none' | 'hybrid' | 'remote'  what the work allows ('none')
//   payModel   'salary' | 'hourly' | 'commission' | 'tips' | 'fees'  ('salary')
//   values     what the work offers besides money: stability, creativity, service,
//              autonomy, prestige, excitement, community, outdoors, craft, care
//   outside    false where the role forbids other paid work (judges, diplomats, intelligence)
//   from       [{ career, level }]  the tracks and rungs this one branches off; held in
//              that track for its time, the player may move across (engine/workplace.js)
//   branchOnly true when it is reached only by branching or experience, never hired cold
//   req.experience { careerId: years }  years in any one of these (summed across employers)
//   req.programs [program ids]  every one of these
//   titlesBy   { countryId: [titles per level] } where a country names the ranks differently
//   aliases    other names people give the work (for search and the source audit)
//
// Pay is in thousands of base units a year at full time. It is gameplay
// configuration, scaled by country wages and city pay (localWage, payK),
// not a statement of what anyone earns anywhere.
const L = (...levels) => levels.map(([title, lo, hi, years, needs]) => ({ title, pay: [lo, hi], years, needs }));

