// Shorthands for the requirements most tracks share.
const HIGH = { degree: 'high' };
const ADULT = { minAge: 18 };
const uni = (...majors) => ({ degree: 'university', ...(majors.length ? { majors } : {}) });

/** A track. Defaults: full-time, interview, stress 1. */
const T = (id, name, family, o, levels) => ({
  id, name, family, category: o.category ?? (['audition', 'portfolio'].includes(o.hire) ? 'performing' : 'catalog'), type: o.type ?? 'fulltime',
  hire: o.hire ?? 'interview', stress: o.stress ?? 1, req: o.req ?? {}, levels, ...o,
});

